<script setup>
import { ref,computed,watch,onMounted,onUnmounted,nextTick } from 'vue'
import { BookOpen,ArrowUpRight,ArrowRight,ArrowLeft,Search,Download,Settings,Network,Database,Calculator,LockKeyhole,Braces,FileText,Check,CheckCircle2,Clock,ChevronRight,X,Menu,FolderOpen,Bookmark,Printer,RotateCcw,Command,ExternalLink,Info,Layers,Terminal,GraduationCap,PanelLeftClose,Sun,Moon,Monitor } from 'lucide-vue-next'
import { courses } from './data/courses'
import {progressKey,route,parseRoute} from './data/course-meta'
import LessonBlocks from './components/LessonBlocks.vue'
const icons={Settings,Network,Database,Calculator,LockKeyhole,Braces,FileText}
function stored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const theme=ref(stored('spravka-theme','light')==='dark'?'dark':'light')
watch(theme,value=>{document.documentElement.dataset.theme=value;try{localStorage.setItem('spravka-theme',JSON.stringify(value))}catch{}},{immediate:true})
const db=ref(stored('spravka-db','postgres')),mode=ref(stored('spravka-mode','gia')),checks=ref(stored('spravka-checks',{}))
if(!['postgres','mssql'].includes(db.value))db.value='postgres'
if(!['gia','pa'].includes(mode.value))mode.value='gia'
const selected=ref(stored('spravka-track',null)),choosing=ref(!courses[selected.value])
if(!courses[selected.value])selected.value='information-systems'
const course=computed(()=>courses[selected.value]),lessons=computed(()=>course.value.lessons),glossary=computed(()=>course.value.glossary),resources=computed(()=>course.value.resources)
const href=(id,section='')=>route(selected.value,id,section)
function selectCourse(id){selected.value=id;choosing.value=false;query.value='';glossaryQuery.value='';try{localStorage.setItem('spravka-track',JSON.stringify(id))}catch{};navigate('overview')}
function chooseSpecialty(){searchOpen.value=false;mobileOpen.value=false;window.location.hash='#specialties';choosing.value=true;window.scrollTo({top:0})}
const active=ref('overview'),searchOpen=ref(false),query=ref(''),mobileOpen=ref(false),searchInput=ref(null),saveStatus=ref(''),resetOpen=ref(false)
const currentSection=ref('')
function trackSection(){const sections=[...document.querySelectorAll('.lesson-section,.lesson-checklist')];currentSection.value=(sections.filter(section=>section.getBoundingClientRect().top<=145).at(-1)||sections[0])?.id||''}
watch(active,async()=>{await nextTick();trackSection()})
const shownLessons=computed(()=>mode.value==='pa'?lessons.value.slice(0,course.value.paCount+1):lessons.value)
const tasks=computed(()=>shownLessons.value.filter(l=>l.id!=='setup'))
const current=computed(()=>lessons.value.find(l=>l.id===active.value))
const currentIndex=computed(()=>shownLessons.value.findIndex(l=>l.id===active.value))
const key=(id,index)=>progressKey(selected.value,id,index)
function isDone(lesson){return lesson.checks.every((_,i)=>checks.value[key(lesson.id,i)])}
const done=computed(()=>tasks.value.filter(isDone).length)
const allCheckCount=computed(()=>tasks.value.reduce((n,l)=>n+l.checks.length,0))
const checkCount=computed(()=>tasks.value.reduce((n,l)=>n+l.checks.filter((_,i)=>checks.value[key(l.id,i)]).length,0))
const percent=computed(()=>Math.round(checkCount.value/allCheckCount.value*100))
const nextLesson=computed(()=>shownLessons.value.find(l=>!isDone(l))||shownLessons.value.at(-1))
const modeTime=computed(()=>mode.value==='pa'?course.value.paTime:'3 ч 30 мин')
const searchResults=computed(()=>{
const q=query.value.trim().toLocaleLowerCase('ru');if(!q)return shownLessons.value.slice(0,5).map(l=>({title:l.title,label:'Задание '+l.number,id:l.id,section:'',snippet:l.summary}))
const results=[]
for(const lesson of shownLessons.value){
if((lesson.title+' '+lesson.summary+' '+lesson.short).toLocaleLowerCase('ru').includes(q))results.push({title:lesson.title,label:'Задание '+lesson.number,id:lesson.id,section:'',snippet:lesson.summary})
for(const section of lesson.sections){const text=section.blocks.map(b=>b.text||b.title||b.items?.join(' ')||b.rows?.flat().join(' ')||'').join(' ');if((section.title+' '+text).toLocaleLowerCase('ru').includes(q))results.push({title:section.title,label:lesson.title,id:lesson.id,section:section.id,snippet:text.slice(Math.max(0,text.toLocaleLowerCase('ru').indexOf(q)-50),Math.max(0,text.toLocaleLowerCase('ru').indexOf(q)-50)+130)})}
}
for(const [term,definition] of glossary.value)if((term+' '+definition).toLocaleLowerCase('ru').includes(q))results.push({title:term,label:'Словарь',id:'glossary',section:'',snippet:definition})
return results.slice(0,25)
})
const glossaryQuery=ref('')
const filteredGlossary=computed(()=>glossary.value.filter(row=>row.join(' ').toLocaleLowerCase('ru').includes(glossaryQuery.value.toLocaleLowerCase('ru'))))
watch(db,value=>{try{localStorage.setItem('spravka-db',JSON.stringify(value))}catch{saveStatus.value='Браузер не разрешил сохранение настроек'}})
watch(mode,value=>{try{localStorage.setItem('spravka-mode',JSON.stringify(value))}catch{};if(!shownLessons.value.some(l=>l.id===active.value)&&current.value)navigate('overview')})
watch(checks,value=>{try{localStorage.setItem('spravka-checks',JSON.stringify(value));saveStatus.value='Прогресс сохранён в этом браузере'}catch{saveStatus.value='Прогресс доступен только до закрытия страницы'}},{deep:true})
let returnFocus=null
watch([searchOpen,resetOpen],async ([search,resetDialog],[oldSearch,oldReset])=>{if((search||resetDialog)&&!oldSearch&&!oldReset)returnFocus=document.activeElement;await nextTick();if(search)searchInput.value?.focus();else if(resetDialog)document.querySelector('.reset-modal button')?.focus();else if(!search&&!resetDialog){returnFocus?.focus?.();returnFocus=null}if(!search)query.value=''})
async function syncHash(){const parsed=parseRoute(window.location.hash);if(parsed.chooser){choosing.value=true;mobileOpen.value=false;document.title='Выбор специальности — По полочкам';return}if(parsed.course){selected.value=parsed.course;choosing.value=false;try{localStorage.setItem('spravka-track',JSON.stringify(parsed.course))}catch{}}else if(choosing.value)return;const id=parsed.id||'overview',section=parsed.section;active.value=shownLessons.value.some(l=>l.id===id)||['overview','glossary','resources','cheatsheet'].includes(id)?id:'overview';mobileOpen.value=false;await nextTick();if(section){document.getElementById(section)?.scrollIntoView({behavior:'smooth',block:'start'})}else window.scrollTo({top:0,behavior:'instant'});document.title=(current.value?.title||{overview:'Главная',glossary:'Словарь',resources:'Материалы',cheatsheet:'Перед сдачей'}[active.value])+' · '+course.value.short+' — По полочкам'}
function navigate(id,section=''){choosing.value=false;searchOpen.value=false;const hash=href(id,section);if(window.location.hash===hash)syncHash();else window.location.hash=hash}
function markDone(){const value=!isDone(current.value);current.value.checks.forEach((_,i)=>checks.value[key(current.value.id,i)]=value)}
function reset(){const copy={...checks.value};for(const lesson of lessons.value)lesson.checks.forEach((_,i)=>delete copy[key(lesson.id,i)]);checks.value=copy;resetOpen.value=false}
function keyboard(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&!choosing.value){event.preventDefault();searchOpen.value=!searchOpen.value}if(event.key==='Escape'){searchOpen.value=false;mobileOpen.value=false;resetOpen.value=false}if(event.key==='Tab'&&(searchOpen.value||resetOpen.value)){const dialog=document.querySelector(searchOpen.value?'.search-modal':'.reset-modal'),items=[...dialog.querySelectorAll('button,a[href],input,select,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length),first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last?.focus()}else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first?.focus()}}}
function printPage(){window.print()}
function focusMain(){document.getElementById('main')?.focus()}
onMounted(()=>{syncHash();window.addEventListener('hashchange',syncHash);window.addEventListener('keydown',keyboard);window.addEventListener('scroll',trackSection,{passive:true})})
onUnmounted(()=>{window.removeEventListener('hashchange',syncHash);window.removeEventListener('keydown',keyboard);window.removeEventListener('scroll',trackSection)})
</script>
<template>
<a href="#main" class="skip-link" @click.prevent="focusMain">Перейти к содержанию</a>
<div :class="['app-shell',{'choosing-specialty':choosing}]">
<div v-if="mobileOpen" class="nav-scrim" @click="mobileOpen=false"></div>
<aside :class="['sidebar',{open:mobileOpen}]" aria-label="Навигация по методичке">
<button class="mobile-close icon-button" @click="mobileOpen=false" aria-label="Закрыть меню"><X :size="20"/></button>
<div class="edition"><span class="edition-dot"></span>ДЕМОЭКЗАМЕН <b>2027</b></div>
<button v-if="!choosing" class="course-switcher" @click="chooseSpecialty"><GraduationCap :size="18"/><span><small>ВАШЕ НАПРАВЛЕНИЕ</small><b>{{course.short}}</b></span><ChevronRight :size="15"/></button>
<button v-if="!choosing" class="sidebar-search" @click="searchOpen=true"><Search :size="16"/><span>Найти в методичке</span><kbd>⌘ K</kbd></button>
<nav v-if="!choosing" class="main-nav"><a :href="href('overview')" :class="{active:active==='overview'}" :aria-current="active==='overview'?'page':undefined"><BookOpen :size="18"/><span>Обзор экзамена</span></a>
<div class="nav-label">ВАШ МАРШРУТ <span>{{tasks.length}} {{tasks.length<5?'ЗАДАНИЯ':'ЗАДАНИЙ'}}</span></div>
<a v-for="lesson in shownLessons" :key="lesson.id" :href="href(lesson.id)" :class="['lesson-nav',{active:active===lesson.id,complete:isDone(lesson)}]" :aria-current="active===lesson.id?'page':undefined"><span class="nav-number"><Check v-if="isDone(lesson)" :size="13"/><template v-else>{{lesson.number}}</template></span><span>{{lesson.id==='setup'?'Подготовка':lesson.title}}</span><span v-if="lesson.time" class="nav-minutes">{{lesson.time}}′</span></a>
<div class="nav-label nav-more">ПОД РУКОЙ</div><a :href="href('glossary')" :class="{active:active==='glossary'}" :aria-current="active==='glossary'?'page':undefined"><Bookmark :size="17"/><span>Словарь по-человечески</span></a><a :href="href('cheatsheet')" :class="{active:active==='cheatsheet'}" :aria-current="active==='cheatsheet'?'page':undefined"><CheckCircle2 :size="17"/><span>Перед сдачей</span></a><a :href="href('resources')" :class="{active:active==='resources'}" :aria-current="active==='resources'?'page':undefined"><FolderOpen :size="17"/><span>Файлы и материалы</span></a></nav>
<div v-if="choosing" class="chooser-navigation"><span class="nav-label">НАЧНИТЕ ЗДЕСЬ</span><div class="chooser-nav-title"><BookOpen :size="18"/>Выбор направления</div><p>Один экзамен — разные задания. Найдите свою квалификацию и начните с подготовки.</p><span class="chooser-nav-note"><Monitor :size="17"/>Windows · C# · .NET</span></div><div v-if="!choosing" class="sidebar-bottom"><div class="progress-label"><span>Ваш прогресс</span><b>{{percent}}%</b></div><div class="progress-track"><span :style="{width:percent+'%'}"></span></div><p>{{done}} из {{tasks.length}} заданий готовы</p><div class="sidebar-source">КИМ {{course.kim}}<br><span>{{course.title}}</span></div></div>
</aside>
<div class="workspace"><header class="topbar"><div class="topbar-left"><a class="brand header-brand" :href="href('overview')"><span class="brand-symbol"><Layers :size="23" :stroke-width="1.5"/></span><span>по полочкам<span class="brand-sub">МЕТОДИЧКА БЕЗ ПАНИКИ</span></span></a><button class="mobile-toggle icon-button" @click="mobileOpen=true" aria-label="Открыть меню"><Menu :size="21"/></button><span class="breadcrumb">Методичка <ChevronRight :size="13"/> <b>{{choosing?'Специальности':current?`Задание ${current.number}`:{overview:'Обзор',glossary:'Словарь',resources:'Материалы',cheatsheet:'Перед сдачей'}[active]}}</b></span></div>
<div class="topbar-actions"><button class="icon-button theme-toggle" @click="theme=theme==='light'?'dark':'light'" :aria-label="theme==='light'?'Включить тёмную тему':'Включить светлую тему'" :title="theme==='light'?'Тёмная тема':'Светлая тема'"><Moon v-if="theme==='light'" :size="18"/><Sun v-else :size="18"/></button><label v-if="!choosing" class="mode-selector"><GraduationCap :size="16"/><select v-model="mode" aria-label="Вид экзамена"><option value="gia">ГИА · Базовый</option><option value="pa">ПА · {{course.paCount}} задания</option></select></label><a v-if="!choosing" class="download-top" :href="course.download" download><Download :size="15"/><span>Пример .NET</span><span class="file-label">ZIP</span></a></div></header>
<main id="main" tabindex="-1">
<template v-if="choosing"><div class="page-heading specialty-heading"><div class="eyebrow">ДЕМОЭКЗАМЕН 2027 · 09.02.07</div><span class="welcome-label"><BookOpen :size="15"/>МЕТОДИЧКА БЕЗ ПАНИКИ</span><h1>Начните со своего<br>направления<span class="heading-dot">.</span></h1><p class="page-subtitle">Всё для подготовки к демоэкзамену: понятные шаги,<br class="desktop-break"> рабочие примеры и проверка результата.</p></div><div class="specialty-grid"><button v-for="item in courses" :key="item.id" class="specialty-card" @click="selectCourse(item.id)"><span class="specialty-symbol"><Braces v-if="item.id==='programmer'" :size="32"/><Network v-else :size="32"/></span><span class="eyebrow">КИМ {{item.kim}}</span><h2>{{item.title}}</h2><p>{{item.description}}</p><div class="specialty-meta"><span>{{item.domain}}</span><span>ПА: {{item.paCount}} · ГИА: {{item.lessons.length-1}} {{item.lessons.length-1<5?'задания':'заданий'}}</span></div><span class="card-link">Выбрать направление <ArrowUpRight :size="19"/></span></button></div><div class="scope-note"><Info :size="19"/><p>Обе квалификации относятся к специальности 09.02.07, но задания у них разные. Направление можно сменить в меню. Чек-листы сохраняются отдельно.</p></div></template>
<template v-else-if="active==='overview'">
<section class="hero docs-hero"><div class="hero-text"><span class="welcome-label"><BookOpen :size="15"/>ВАША МЕТОДИЧКА ПО ДЕМОЭКЗАМЕНУ</span><h1>Всё по полочкам<span class="heading-dot">.</span></h1><p>{{course.subtitle}}</p><button class="hero-search" @click="searchOpen=true"><Search :size="21"/><span>Что хотите разобрать?</span><kbd>⌘ K</kbd><ArrowRight :size="19"/></button><div class="hero-stack"><span class="hero-stack-label">В быстрый доступ:</span><button @click="navigate(nextLesson.id)"><Settings :size="14"/>{{percent>0?'Продолжить':'Подготовка'}}</button><button @click="navigate('glossary')"><Bookmark :size="14"/>Словарь</button><button @click="navigate('resources')"><Braces :size="14"/>Примеры .NET</button></div></div></section>
<div class="exam-stats"><div><Clock :size="21"/><span><b>{{modeTime}}</b><small>на выполнение</small></span></div><div><Layers :size="21"/><span><b>{{tasks.length}} {{tasks.length<5?'задания':'заданий'}}</b><small>в вашем маршруте</small></span></div><div><GraduationCap :size="23"/><span><b>{{mode==='pa'?'25':'75'}} баллов</b><small>максимум по КИМ</small></span></div><div><Terminal :size="21"/><span><b>Razor Pages</b><small>примеры на C#</small></span></div></div>
<section class="route-section"><div class="section-heading"><div><span class="eyebrow">ВЫБЕРИТЕ ТЕМУ ДЛЯ РАЗБОРА</span><h2>Разделы методички</h2></div><span class="quiet">Проходите по порядку — задания связаны</span></div><div class="setup-banner"><span class="setup-icon"><Settings :size="19"/></span><div><b>Сначала подготовим рабочее место</b><p>Установим инструменты и запустим пример на Windows.</p></div><button @click="navigate('setup')">Шаг 00 <ArrowRight :size="16"/></button></div>
<div class="task-grid"><button v-for="lesson in tasks" :key="lesson.id" @click="navigate(lesson.id)" :class="['task-card',{done:isDone(lesson)}]"><div class="task-card-top"><span class="task-number">{{lesson.number}}</span><span class="task-duration"><CheckCircle2 v-if="isDone(lesson)" :size="15"/><Clock v-else :size="14"/>{{isDone(lesson)?'Готово':lesson.time+' мин'}}</span></div><div class="task-icon"><component :is="icons[lesson.icon]" :size="25" :stroke-width="1.5"/></div><h3>{{lesson.title}}</h3><p>{{lesson.short}}</p><span class="card-link">Разобрать задание <ArrowUpRight :size="17"/></span></button></div></section>
<section class="bottom-grid"><div class="db-card"><div class="eyebrow">ВЫБЕРИТЕ СВОЙ ВАРИАНТ</div><h3>Одна логика. Две базы.</h3><p>SQL и инструкции меняются под вашу СУБД.<br>Примеры C# работают с обеими.</p><div class="db-switch" role="group" aria-label="Выбор СУБД"><button :class="{selected:db==='postgres'}" :aria-pressed="db==='postgres'" @click="db='postgres'">PostgreSQL<Check v-if="db==='postgres'" :size="14"/></button><button :class="{selected:db==='mssql'}" :aria-pressed="db==='mssql'" @click="db='mssql'">SQL Server<Check v-if="db==='mssql'" :size="14"/></button></div></div><div class="understand-card"><Bookmark :size="22"/><h3>Слова тоже разложим.</h3><p>PK, FK, 3НФ и JOIN — с короткими объяснениями и примерами.</p><button class="text-button" @click="navigate('glossary')">Открыть словарь <ArrowRight :size="16"/></button></div></section>
<div class="scope-note"><Info :size="17"/><p>Методичка разбирает <b>образец заданий</b> из вашего КИМ и приложения. Профильная вариативная часть определяется колледжем и в этих файлах не представлена. Времена взяты из таблицы 11 КИМ.</p></div>
</template>
<template v-else-if="current">
<div class="lesson-heading"><div class="eyebrow">{{current.tag}} <span class="eyebrow-divider">/</span> {{current.time?current.time+' МИНУТ ПО КИМ':'ДО ЭКЗАМЕНА'}}</div><div class="lesson-title-row"><span class="large-number">{{current.number}}</span><div><h1>{{current.title}}</h1><p>{{current.summary}}</p></div></div><div class="lesson-tools"><div class="db-switch small" role="group" aria-label="СУБД для примеров"><button :class="{selected:db==='postgres'}" :aria-pressed="db==='postgres'" @click="db='postgres'">PostgreSQL</button><button :class="{selected:db==='mssql'}" :aria-pressed="db==='mssql'" @click="db='mssql'">SQL Server</button></div><span class="stack-label">C# · Razor Pages · Windows</span><button class="icon-button print-button" @click="printPage" aria-label="Распечатать задание"><Printer :size="18"/></button></div></div>

<div class="article-layout"><article class="lesson-article"><div class="deliverable"><CheckCircle2 :size="22"/><div><span class="mini-tag">ЧТО ДОЛЖНО ПОЛУЧИТЬСЯ</span><p>{{current.deliverable}}</p></div></div>
<section v-for="(section,index) in current.sections" :key="current.id+'/'+section.id" :id="section.id" class="lesson-section"><h2><span>{{index+1}}</span>{{section.title}}</h2><LessonBlocks :blocks="section.blocks" :db="db" :code-set="course.codes"/></section>
<section id="checklist" class="lesson-checklist"><div class="checklist-heading"><span class="checklist-icon"><CheckCircle2 :size="24"/></span><div><span class="eyebrow">СЕБЕ МОЖНО ДОВЕРЯТЬ. ЛУЧШЕ ПРОВЕРИТЬ.</span><h2>Готово, если…</h2></div><span>{{current.checks.filter((_,i)=>checks[key(current.id,i)]).length}} / {{current.checks.length}}</span></div><label v-for="(check,index) in current.checks" :key="key(current.id,index)" :class="{checked:checks[key(current.id,index)]}"><input type="checkbox" v-model="checks[key(current.id,index)]"><span>{{check}}</span></label><p class="quiet">Отметки — ваша самопроверка. Сохраняются в этом браузере.</p></section>
<div class="article-source"><FileText :size="15"/><span>{{current.source}}</span></div><div class="lesson-finish"><button class="btn" :class="isDone(current)?'secondary':'primary'" @click="markDone"><Check :size="17"/>{{isDone(current)?'Снять отметку о готовности':'Отметить задание готовым'}}</button><button v-if="currentIndex>=0&&shownLessons[currentIndex+1]" class="text-button" @click="navigate(shownLessons[currentIndex+1].id)">Дальше: {{shownLessons[currentIndex+1].title}}<ArrowRight :size="17"/></button><button v-else class="text-button" @click="navigate('cheatsheet')">Проверить перед сдачей <ArrowRight :size="17"/></button></div>
</article><aside class="toc" aria-label="Содержание задания"><span class="nav-label">В ЭТОМ ЗАДАНИИ</span><a v-for="(section,i) in current.sections" :key="section.id" :href="href(current.id,section.id)" @click.prevent="navigate(current.id,section.id)" :class="{active:currentSection===section.id}" :aria-current="currentSection===section.id?'location':undefined"><span>{{String(i+1).padStart(2,'0')}}</span>{{section.title}}</a><a :href="href(current.id,'checklist')" @click.prevent="navigate(current.id,'checklist')" :class="{active:currentSection==='checklist'}" :aria-current="currentSection==='checklist'?'location':undefined"><CheckCircle2 :size="14"/>Чек-лист готовности</a><div class="toc-tip"><Bookmark :size="19"/><b>Непонятно слово?</b><p>В словаре — короткое объяснение без сложных формулировок.</p><a :href="href('glossary')">Посмотреть <ArrowRight :size="13"/></a></div><a class="toc-download" :href="course.download" download><Download :size="16"/><span>Весь пример .NET<br><small>Код, SQL и инструкция</small></span></a></aside></div>
</template>
<template v-else-if="active==='glossary'"><div class="page-heading"><div class="eyebrow">СЛОЖНЫЕ СЛОВА · ПРОСТЫЕ ОБЪЯСНЕНИЯ</div><h1>По-человечески.</h1><p class="page-subtitle">Здесь можно не знать терминов. Для этого и нужен словарь.</p></div><label class="glossary-search"><Search :size="18"/><input v-model="glossaryQuery" placeholder="Например, внешний ключ или транзакция" aria-label="Поиск термина"></label><div class="glossary-grid"><div v-for="[term,definition] in filteredGlossary" :key="term" class="glossary-card"><h3>{{term}}</h3><p>{{definition}}</p></div></div><div v-if="!filteredGlossary.length" class="empty-state"><Search :size="30"/><h3>Такого термина пока нет</h3><p>Попробуйте другое слово или очистите поиск.</p><button class="btn secondary" @click="glossaryQuery=''">Показать все термины</button></div></template>
<template v-else-if="active==='resources'"><div class="page-heading"><div class="eyebrow">ПОД РУКОЙ · ВСЁ ИЗ ВАШИХ ФАЙЛОВ</div><h1>Материалы и код.</h1><p class="page-subtitle">Исходные задания, готовый учебный проект и файлы для тренировки.</p></div><div class="resource-grid"><a v-for="resource in resources" :key="resource.url" :href="resource.url" :download="resource.type!=='PDF'" :target="resource.type==='PDF'?'_blank':undefined" rel="noopener" class="resource-card"><span class="resource-type">{{resource.type}}</span><div><h3>{{resource.title}}</h3><p>{{resource.description}}</p></div><ExternalLink v-if="resource.type==='PDF'" :size="18"/><Download v-else :size="18"/></a></div><div class="callout info"><Info :size="19"/><div><strong>Что проверено в примере</strong><p>{{course.verification}} Вариант SQL Server подготовлен с отдельными SQL-скриптами и провайдером Microsoft.Data.SqlClient; подключение к живому SQL Server нужно проверить на вашем Windows-компьютере.</p></div></div><section class="reference-section"><h2>Официальная документация</h2><p>Если хотите понять механизм глубже, эти страницы описывают используемые технологии.</p><a href="https://learn.microsoft.com/en-us/aspnet/core/razor-pages/?view=aspnetcore-10.0" target="_blank" rel="noopener">Microsoft · Razor Pages <ArrowUpRight :size="17"/></a><a href="https://learn.microsoft.com/en-us/aspnet/core/fundamentals/app-state?view=aspnetcore-10.0" target="_blank" rel="noopener">Microsoft · Session в ASP.NET Core <ArrowUpRight :size="17"/></a><a href="https://www.npgsql.org/doc/basic-usage.html" target="_blank" rel="noopener">Npgsql · параметры и чтение PostgreSQL <ArrowUpRight :size="17"/></a></section><div class="callout info"><Info :size="19"/><div><strong>Как устроен пример</strong><p>Сайт-методичка работает без серверной части. Скачанный проект .NET подключается к вашей БД и запускается отдельно под Windows. .NET-пример не требуется для чтения этого сайта.</p></div></div></template>
<template v-else-if="active==='cheatsheet'"><div class="page-heading"><div class="eyebrow">ПОСЛЕДНИЙ ПРОХОД ПЕРЕД СДАЧЕЙ</div><h1>Собрать всё вместе.</h1><p class="page-subtitle">Работающий код — часть результата. Эксперт должен открыть и проверить всю работу.</p></div><div class="submission-banner"><FolderOpen :size="30"/><div><h3>Одна понятная папка для сдачи</h3><p>Используйте имя и путь, которые указаны на вашей площадке. Структура ниже — учебный пример.</p></div></div><div class="submission-list"><div v-for="lesson in tasks" :key="lesson.id"><span class="submission-number">{{lesson.number}}</span><div><h3>{{lesson.title}}</h3><p>{{lesson.deliverable}}</p></div><button :class="['status-pill',{done:isDone(lesson)}]" @click="navigate(lesson.id,'checklist')"><CheckCircle2 v-if="isDone(lesson)" :size="14"/><template v-else>Проверить</template><template v-if="isDone(lesson)">Готово</template><ChevronRight :size="13"/></button></div></div><div class="table-scroll"><table><thead><tr><th>Папка / файл</th><th>Содержимое</th></tr></thead><tbody v-if="selected==='information-systems'"><tr><td>01_ER/diagram.pdf</td><td>Читаемая схема, ключи и связи</td></tr><tr><td>02_DB/</td><td>schema.sql, seed.sql, JSON, импорт либо backup по правилам площадки</td></tr><tr><td>03_SQL/cost.sql</td><td>Запрос + пояснение выбранных норм и цен</td></tr><template v-if="mode==='gia'"><tr><td>04_App/</td><td>Исходники Razor Pages, изображения, README и настройки подключения</td></tr><tr><td>05_API/</td><td>Коллекция Postman и сохранённые результаты тестов</td></tr><tr><td>06_Docs/API.docx</td><td>Заполненный исходный шаблон</td></tr></template></tbody><tbody v-else><tr><td>01_DB/</td><td>ER-PDF, SQL со схемой и данными, исходники импорта</td></tr><tr><td>02_Catalog/</td><td>Алгоритм и работающий каталог со скидками</td></tr><tr><td>ShoeStore/</td><td>Исходники C#, appsettings, XLSX, графика и README</td></tr><tr><td>publish/</td><td>Публикация для Windows; проверенный запуск</td></tr></tbody></table></div><div v-if="selected==='programmer'" class="callout info"><Info :size="19"/><div><strong>Передача файлов в репозиторий</strong><p>В этом КИМ результат передаётся структурой файлов в репозиторий площадки, не ZIP. Сохраните SQL с актуальными данными. Уберите фиксированную CalculationDate.</p></div></div><div class="callout warning"><Info :size="19"/><div><strong>Проверить открытие важнее красивого имени</strong><p>Откройте PDF, восстановите БД в тестовую копию, распакуйте приложение в другую папку и повторите запуск. {{selected==='programmer'?'Проверьте роли, даты, скидки и восстановление остатков.':'В документе и Postman должен быть фактический URL.'}} Если по времени не успеваете, сохраните уже работающие результаты каждого задания.</p></div></div><div class="review-actions"><button class="btn secondary" @click="printPage"><Printer :size="16"/>Распечатать список</button><button class="text-button danger" @click="resetOpen=true"><RotateCcw :size="15"/>Сбросить прогресс тренировки</button></div></template>
<footer class="page-footer"><span><Layers :size="15"/>по полочкам <span>·</span> можно разобраться</span><span>{{choosing?'Windows · C# · .NET':'КИМ '+course.kim+' · Учебная методичка'}}</span></footer>
</main></div></div>
<div v-if="searchOpen" class="modal-overlay" @click.self="searchOpen=false"><section class="search-modal" role="dialog" aria-modal="true" aria-labelledby="search-title"><h2 id="search-title" class="sr-only">Поиск по методичке</h2><div class="search-modal-input"><Search :size="22"/><input ref="searchInput" v-model="query" placeholder="Задание, термин или ошибка…" aria-label="Поиск по методичке" @keydown.enter="searchResults[0]&&navigate(searchResults[0].id,searchResults[0].section)"><button class="icon-button" @click="searchOpen=false" aria-label="Закрыть поиск"><X :size="20"/></button></div><p class="search-label">{{query?`Найдено: ${searchResults.length}`:'БЫСТРЫЙ ПЕРЕХОД'}}</p><div class="search-results"><button v-for="(result,index) in searchResults" :key="index" @click="navigate(result.id,result.section)"><div><small>{{result.label}}</small><h3>{{result.title}}</h3><p v-if="query">{{result.snippet}}</p></div><ArrowUpRight :size="18"/></button><div v-if="!searchResults.length" class="empty-state"><Search :size="26"/><h3>Ничего не нашли</h3><p>Попробуйте другое слово из заданий выбранного направления.</p></div></div><div class="search-footer"><span>Enter — открыть первый результат</span><span>Esc — закрыть</span></div></section></div>
<div v-if="resetOpen" class="modal-overlay" @click.self="resetOpen=false"><section class="reset-modal" role="dialog" aria-modal="true" aria-labelledby="reset-title"><RotateCcw :size="28"/><h2 id="reset-title">Начать новую тренировку?</h2><p>Отметки направления «{{course.short}}» будут сняты. Прогресс другого направления и настройки СУБД сохранятся.</p><div><button class="btn secondary" @click="resetOpen=false">Оставить прогресс</button><button class="btn primary" @click="reset">Сбросить отметки</button></div></section></div>
<div class="sr-only" role="status">{{saveStatus}}</div>
</template>
